/** Hidden sprite, printed once right after <body>. */
function icon_sprite(): string
{
    $out = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">';
    foreach (icon_paths() as $name => $paths) {
        $out .= '<symbol id="i-' . $name . '" viewBox="0 0 24 24">' . $paths . '</symbol>';
    }
    return $out . '</svg>';
}

/** An icon. Pass $label for a meaningful icon; decorative icons are hidden from screen readers. */
function icon(string $name, string $class = '', ?string $label = null): string
{
    $a11y = $label !== null ? ' role="img" aria-label="' . e($label) . '"' : ' aria-hidden="true" focusable="false"';
    return '<svg class="icon' . ($class !== '' ? ' ' . e($class) : '') . '"' . $a11y . '><use href="#i-' . e($name) . '"/></svg>';
}

/** The Veridian mark (gradient tile, V-check and gold dot). */
function brand_mark(string $class = 'brand__mark', string $idSuffix = ''): string
{
    $id = 'vg' . ($idSuffix !== '' ? $idSuffix : substr(md5(uniqid('', true)), 0, 6));
    return '<svg class="' . e($class) . '" viewBox="0 0 100 100" aria-hidden="true" focusable="false">'
        . '<defs><linearGradient id="' . $id . '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#1E8E72"/><stop offset="1" stop-color="#0A3A31"/></linearGradient></defs>'
        . '<rect width="100" height="100" rx="22" fill="url(#' . $id . ')"/>'
        . '<path d="M26 35 L46 70 L72 30" fill="none" stroke="#fff" stroke-width="11" stroke-linecap="round" stroke-linejoin="round"/>'
        . '<circle cx="80.5" cy="18.5" r="6.5" fill="#E3B341"/></svg>';
}
